namespace SirketMotoru.Isletim;

public static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Şirket Yönetim Merkezi v4</title>
<style>
:root{color-scheme:dark;--bg:#050914;--p:#0b1424;--p2:#101d31;--l:#263a59;--t:#eef5ff;--m:#91a6c2;--g:#45e2a2;--b:#65a9ff;--r:#ff6d7e;--y:#ffd166;--s:0 16px 48px #0008}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 10% 0,#10284b 0,transparent 35%),var(--bg);color:var(--t);font-family:Inter,Segoe UI,Arial,sans-serif}body{padding:12px}button,input,select{font:inherit}.shell{max-width:2000px;margin:auto}.top{position:sticky;top:7px;z-index:20;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 15px;border:1px solid var(--l);border-radius:16px;background:#091424ed;box-shadow:var(--s)}.brand{font-size:18px;font-weight:950}.brand small{display:block;margin-top:3px;color:var(--m);font-size:10px;font-weight:500}.status,.tabs,.tags,.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.status{justify-content:flex-end}.pill,.tag{padding:6px 9px;border:1px solid var(--l);border-radius:999px;background:#0a1628;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.hidden,[hidden]{display:none!important}.login{max-width:450px;margin:10vh auto;padding:22px;border:1px solid var(--l);border-radius:18px;background:var(--p);box-shadow:var(--s)}.tabs{margin:12px 0}.tab,button{cursor:pointer;border:1px solid transparent;border-radius:9px;padding:9px 12px;background:var(--g);color:#032018;font-weight:850}.tab{background:#0a1628;color:var(--m);border-color:var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#04141d}.secondary{background:#203653;color:var(--t)}.danger{background:var(--r);color:#fff}.small{font-size:10px;padding:7px 9px}.full{width:100%;margin-top:9px}button:disabled{opacity:.42;cursor:not-allowed}.banner,.notice{margin:11px 0;padding:10px 12px;border:1px solid var(--l);border-radius:11px;color:var(--m)}.banner{border-color:#6d592b;background:#211d12;color:var(--y)}.notice.good,.good{color:var(--g);border-color:#28634f}.notice.bad,.bad{color:var(--r);border-color:#743746}.warn{color:var(--y)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:8px;margin:12px 0}.metric,.item{padding:10px;border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:7px;font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.panel{display:grid;gap:11px}.card{padding:13px;border:1px solid var(--l);border-radius:15px;background:linear-gradient(180deg,#101b2eeb,#08101deb);box-shadow:var(--s);overflow:hidden}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.item h3{margin:0 0 5px;font-size:14px}.item p{margin:4px 0;color:var(--m);font-size:10px}.row{justify-content:space-between}.title{display:flex;justify-content:space-between;align-items:center;gap:9px;margin-bottom:10px}.title h2{margin:0;font-size:15px}label{display:block;color:var(--m);font-size:9px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}input:focus,select:focus{outline:none;border-color:var(--b);box-shadow:0 0 0 3px #65a9ff20}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:8px}.tablewrap{overflow:auto;max-height:720px}table{width:100%;border-collapse:collapse;min-width:1180px;font-size:10px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:9px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l)}td{padding:9px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right;font-variant-numeric:tabular-nums}.bar{height:7px;background:#152239;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.event,.tx{padding:7px 0;border-bottom:1px solid var(--l);font-size:9px}.tx{display:grid;grid-template-columns:55px 115px 1fr auto;gap:7px}.busy{position:fixed;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--g),var(--b),#b68cff);transform:scaleX(0);transform-origin:left;z-index:100}.busy.on{transform:scaleX(1)}#toast{position:fixed;right:14px;bottom:14px;max-width:480px;z-index:90;background:#10243b;box-shadow:var(--s)}@media(max-width:1450px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){body{padding:6px}.top{position:static;align-items:flex-start;flex-direction:column}.status{justify-content:flex-start}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.grid4,.form{grid-template-columns:1fr}.tx{grid-template-columns:55px 1fr}}
</style>
</head>
<body>
<div id="busy" class="busy"></div>
<div class="shell">
<header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ v4<small>Kalıcı motor otoritesi · kapasite · ürün ekosistemi · finans · risk</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANTI YOK</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Genel</b></span><span class="pill">Son veri <b id="updated">—</b></span><button id="logout" type="button" class="secondary small hidden">Çıkış</button></div></header>
<section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Kod sunucuda yazılır; motor kalıcı ticari verinin otoritesidir.</p><label>Kullanıcı adı<input id="username" autocomplete="username"></label><label>Parola<input id="password" type="password" autocomplete="current-password"></label><button id="login" type="button" class="full">Giriş yap</button><div id="loginMsg" class="notice">Geçici hesap bilgileri motor konsolunda görünür.</div></section>
<main id="app" class="hidden"><div class="banner"><b>Kural:</b> Sunucunun gönderdiği fiyat, kapasite ve aktiflik yalnız ilk varsayılandır. 8090 değişiklikleri kalıcı kayda yazılır ve yeniden bağlantıda korunur.</div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"><button type="button" class="tab active" data-panel="overview">Genel</button><button type="button" class="tab" data-panel="services">Hizmetler & Kapasite</button><button type="button" class="tab" data-panel="products">Ürünler</button><button type="button" class="tab" data-panel="infra">Altyapı</button><button type="button" class="tab" data-panel="bank">Banka</button><button type="button" class="tab" data-panel="protocols">Protokoller</button><button type="button" class="tab" data-panel="contracts">Sözleşmeler</button><button type="button" class="tab" data-panel="account">Hesap</button></nav><section id="overview" class="panel"></section><section id="services" class="panel" hidden></section><section id="products" class="panel" hidden></section><section id="infra" class="panel" hidden></section><section id="bank" class="panel" hidden></section><section id="protocols" class="panel" hidden></section><section id="contracts" class="panel" hidden></section><section id="account" class="panel" hidden></section></main>
</div><div id="toast" class="notice hidden"></div>
<script>
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0));
const num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0));
const int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={data:null,active:'overview',loading:false,busy:false,timer:null,pending:null,drafts:new Map(),toastTimer:null};
const field=(key,value,type='number',attrs='')=>`<input data-key="${esc(key)}" type="${type}" value="${esc(S.drafts.has(key)?S.drafts.get(key):value??'')}" ${attrs}>`;
const selectField=(key,value,options)=>{const selected=String(S.drafts.has(key)?S.drafts.get(key):value);return `<select data-key="${esc(key)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===selected?'selected':''}>${esc(t)}</option>`).join('')}</select>`};
function switchPanel(id){const target=document.getElementById(id)||document.getElementById('overview');S.active=target.id;$$('.panel').forEach(p=>p.hidden=p!==target);$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===target.id));$('#panelName').textContent=document.querySelector(`.tab[data-panel="${target.id}"]`)?.textContent||target.id;history.replaceState(null,'',`#${target.id}`)}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('button[data-panel]');if(!b)return;e.preventDefault();switchPanel(b.dataset.panel)});
function editing(){return S.busy||!!document.activeElement?.matches('input,select,textarea')}
function toast(text,ok=true){const e=$('#toast');clearTimeout(S.toastTimer);e.textContent=text;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');S.toastTimer=setTimeout(()=>e.classList.add('hidden'),5000)}
async function request(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(!r.ok||d.basarili===false)throw new Error(d.aciklama||`HTTP ${r.status}`);return d}
function showApp(){$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');switchPanel(location.hash.slice(1)||'overview')}
async function login(){try{const r=await request('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();toast(r.aciklama||'Giriş başarılı.');await refresh(true);startPolling()}catch(e){$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad'}}
async function logout(){try{await request('/api/cikis',{})}catch{}clearInterval(S.timer);location.reload()}
function startPolling(){clearInterval(S.timer);S.timer=setInterval(()=>refresh(false),1000)}
async function refresh(force=false){if(S.loading)return;S.loading=true;try{const d=await request(`/api/durum?t=${Date.now()}`);S.data=d;$('#dot').classList.add('ok');$('#conn').textContent='CANLI';$('#tick').textContent=d.tickNumarasi??0;$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');renderMetrics(d);if(force||!editing()){S.pending=null;renderAll(d)}else S.pending=d}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='HATA';if(String(e.message).includes('Oturum'))location.reload()}finally{S.loading=false}}
function renderMetrics(d){const s=d.sirket||{},i=d.isletim||{},k=d.kapasiteOzeti||{};const values=[['Kasa',money(s.kasa)],['Şirket değeri',money(i.sirketDegeri)],['Toplam işlem kapasitesi',int(k.toplamEszamanliIslemKapasitesi)],['Uygulama kapasitesi',int(k.toplamUygulamaKullaniciKapasitesi)],['Aktif kullanıcı',int(k.toplamAktifKullanici)],['Doluluk',`${num(k.uygulamaDolulukOrani)}%`],['Aktif hizmet',int(k.aktifHizmetSayisi)],['Satın alınan app kapasitesi',int(k.toplamSatinAlinanUygulamaKapasitesi)],['Altyapı kapasite bonusu',int(k.toplamAltyapiKapasiteBonusu)],['Operasyon riski',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Toplam borç',money(i.toplamBorc)]];$('#metrics').innerHTML=values.map(x=>`<div class="metric"><span>${esc(x[0])}</span><b>${esc(x[1])}</b></div>`).join('')}
function renderAll(d){renderOverview(d);renderServices(d);renderProducts(d);renderInfra(d);renderBank(d);renderProtocols(d);renderContracts(d);renderAccount(d);switchPanel(S.active)}
function renderOverview(d){const s=d.sirket||{},i=d.isletim||{},k=d.kapasiteOzeti||{};const events=(i.sonOlaylar||[]).map(o=>`<div class="event"><div class="row"><b class="${o.olumlu?'good':'bad'}">${esc(o.baslik)}</b><span>T${o.tickNumarasi}</span></div><p>${esc(o.aciklama)}</p><div class="tags"><span class="tag">Finans ${money(o.finansalEtki)}</span><span class="tag">İtibar ${num(o.itibarEtkisi)}</span><span class="tag">Performans ${num(o.performansEtkisi)}</span></div></div>`).join('')||'<div class="notice">Henüz şirket olayı yok.</div>';const tx=(i.sonIslemler||[]).map(x=>`<div class="tx"><span>T${x.tickNumarasi}</span><b>${esc(x.islemTuru)}</b><span>${esc(x.aciklama)}</span><strong class="${Number(x.tutar)>=0?'good':'bad'}">${money(x.tutar)}</strong></div>`).join('')||'<div class="notice">İşlem kaydı yok.</div>';$('#overview').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Şirket ve kapasite özeti</h2><span class="tag ${s.bagliMi?'good':'bad'}">${s.bagliMi?'SUNUCU BAĞLI':'SUNUCU KAPALI'}</span></div><div class="grid4">${[['Toplam eşzamanlı işlem',int(k.toplamEszamanliIslemKapasitesi)],['Toplam uygulama kapasitesi',int(k.toplamUygulamaKullaniciKapasitesi)],['Aktif kullanıcı',int(k.toplamAktifKullanici)],['Doluluk',`${num(k.uygulamaDolulukOrani)}%`],['Kod kalitesi',num(s.kodKalitesiPuani)],['Performans',num(s.performansPuani)],['Güvenlik',num(s.guvenlikPuani)],['Bakım baskısı',num(i.bakimBaskisi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Dinamik şirket olayları</h2><span class="tag warn">Kusursuz şirket de olay yaşayabilir</span></div>${events}</div></div><div class="card"><div class="title"><h2>Kalıcı işletim hareketleri</h2></div>${tx}</div>`}
function serviceList(){return S.data?.kodTabanliYayinlar?.hizmetler||[]}
function renderServices(d){const list=d.kodTabanliYayinlar?.hizmetler||[];$('#services').innerHTML=`<div class="card"><div class="title"><div><h2>Hizmetler ve işlem kapasitesi</h2><span class="sub">Etkin kapasite = ilk sunucu kapasitesi + satın alınan kapasite + yatırım bonusu</span></div><span class="tag good">Toplam ${int(d.kapasiteOzeti?.toplamEszamanliIslemKapasitesi)}</span></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th>Fiyat</th><th>İlk fiyat</th><th class="num">Baz</th><th class="num">Satın alınan</th><th class="num">Yatırım bonusu</th><th class="num">Etkin</th><th>Durum</th><th>Kapasite al</th><th>İşlem</th></tr></thead><tbody>${list.map(h=>{const id=`${h.hizmetKimligi}@${h.hizmetSurumu}`;return `<tr><td><b>${esc(h.hizmetKimligi)}</b><span class="sub">v${esc(h.hizmetSurumu)}</span></td><td>${field(`svc:${id}:price`,h.birimFiyat,'number','min="0.01" step="0.01"')}</td><td>${money(h.sunucuDefaultFiyat)}</td><td class="num">${int(h.bazKapasite)}</td><td class="num good">${int(h.satinAlinanKapasite)}</td><td class="num warn">${int(h.yatirimKapasiteBonusu)}</td><td class="num"><b>${int(h.etkinKapasite)}</b></td><td><span class="tag ${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</span></td><td>${field(`svc:${id}:cap`,1,'number','min="1" max="500"')}<button type="button" class="small secondary" data-action="service-cap" data-id="${esc(id)}">Satın al</button></td><td><button type="button" class="small" data-action="service-price" data-id="${esc(id)}">Fiyatı kaydet</button> <button type="button" class="small ${h.aktif?'danger':'secondary'}" data-action="service-toggle" data-id="${esc(id)}">${h.aktif?'Pasife al':'Aktife al'}</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function renderProducts(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],products=d.isletim?.urunler||[];$('#products').innerHTML=`<div class="card"><div class="title"><div><h2>Koddan ilan edilen serbest ürünler</h2><span class="sub">Uygulama, işletim sistemi, platform, altyapı, oyun veya özel bir tür olabilir.</span></div><span class="tag">${apps.length} manifest</span></div>${apps.map(appCard).join('')||'<div class="notice">Manifest yok.</div>'}</div><div class="card"><div class="title"><h2>Piyasadaki ürünler</h2><span class="tag good">Kapasite ${int(d.kapasiteOzeti?.toplamUygulamaKullaniciKapasitesi)}</span></div>${products.map(productCard).join('')||'<div class="notice">Piyasada ürün yok.</div>'}</div>`}
function appCard(x){const a=x.uygulama||{},v=x.dogrulama||{},id=a.uygulamaKimligi;return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">${esc(a.urunTuru||'uygulama')}</span></h3><p>${esc(a.aciklama)} · v${esc(a.surum)}</p></div><span class="tag ${v.gecerli?'good':'bad'}">${v.gecerli?'GEÇERLİ':'EKSİK'}</span></div><div class="tags"><span class="tag">${esc(a.kategori)}</span>${(a.desteklenenPlatformlar||[]).map(p=>`<span class="tag good">Destek ${esc(p)}</span>`).join('')}${(a.gerekliPlatformlar||[]).map(p=>`<span class="tag warn">Gerekli ${esc(p)}</span>`).join('')}${(a.bagimliliklar||[]).map(b=>`<span class="tag">${esc(b.sirketKimligi)}/${esc(b.uygulamaKimligi)}</span>`).join('')}</div>${(v.hatalar||[]).map(e=>`<p class="bad">• ${esc(e)}</p>`).join('')}${x.piyasada?`<div class="notice good">Piyasada · ${esc(x.urunKimligi)}</div>`:`<div class="form"><label>Model${selectField(`app:${id}:model`,'abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans'],['tek-seferlik','Tek seferlik']])}</label><label>Abonelik${field(`app:${id}:sub`,25,'number','min="0" step="0.01"')}</label><label>Kullanım${field(`app:${id}:use`,0,'number','min="0" step="0.0001"')}</label><button type="button" data-action="app-publish" data-id="${esc(id)}" ${!v.gecerli||!x.sunucuBagli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}
function productCard(p){const id=p.urunKimligi,occ=Number(p.kullaniciKapasitesi)>0?Number(p.aktifKullaniciSayisi)*100/Number(p.kullaniciKapasitesi):0;return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(p.urunAdi)} <span class="tag">${esc(p.urunTuru||p.kategori)}</span></h3><p>${int(p.aktifKullaniciSayisi)} / ${int(p.kullaniciKapasitesi)} kullanıcı · Doluluk %${num(occ)}</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'DURDU'}</span></div><div class="bar"><i style="width:${Math.min(100,occ)}%"></i></div><div class="tags"><span class="tag">Taban ${int(p.tabanKullaniciKapasitesi)}</span><span class="tag good">Satın alınan ${int(p.satinAlinanKullaniciKapasitesi)}</span><span class="tag warn">Altyapı bonusu ${int(p.altyapiKapasiteBonusu)}</span></div><div class="form"><label>Abonelik${field(`prd:${id}:sub`,p.abonelikUcreti,'number','min="0" step="0.01"')}</label><label>Kullanım${field(`prd:${id}:use`,p.kullanimBasinaUcret,'number','min="0" step="0.0001"')}</label><label>Kapasite ekle${field(`prd:${id}:cap`,100,'number','min="50" max="100000" step="50"')}</label><div><button type="button" class="small" data-action="product-save" data-id="${esc(id)}">Kaydet</button> <button type="button" class="small secondary" data-action="product-cap" data-id="${esc(id)}">Kapasite al</button> <button type="button" class="small ${p.aktif?'danger':'secondary'}" data-action="product-toggle" data-id="${esc(id)}">${p.aktif?'Durdur':'Yayına al'}</button></div></div></div>`}
function renderInfra(d){const list=d.yatirimMagazasi||[];$('#infra').innerHTML=`<div class="card"><div class="title"><div><h2>Altyapı ve departman yatırımları</h2><span class="sub">Kapasite, risk ve kullanıcı davranışına gerçek etki eder; her seviyenin tick bakım gideri vardır.</span></div></div><div class="grid4">${list.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><div class="tags"><span class="tag good">Seviye ${int(x.seviye)}/${int(x.azamiSeviye)}</span><span class="tag warn">Bakım ${money(x.tickBakimGideri)}/tick</span></div><div class="row"><b>${money(x.sonrakiMaliyet)}</b><button type="button" class="small" data-action="investment" data-id="${esc(x.yatirimTuru)}" ${x.seviye>=x.azamiSeviye?'disabled':''}>Satın al</button></div></div>`).join('')}</div></div>`}
function renderBank(d){const packs=d.krediPaketleri||[],loans=d.isletim?.krediler||[];$('#bank').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Kredi paketleri</h2><span class="tag warn">Gerçek taksit ve faiz</span></div>${packs.map(p=>`<div class="item" style="margin-bottom:8px"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)}–${money(p.azamiTutar)} · Not ≥ ${int(p.asgariKrediNotu)}</p><label>Tutar${field(`loan:${p.krediTuru}`,p.asgariTutar,'number',`min="${p.asgariTutar}" max="${p.azamiTutar}" step="100"`)}</label><button type="button" class="full" data-action="loan" data-id="${esc(p.krediTuru)}">Kredi çek</button></div>`).join('')}</div><div class="card"><div class="title"><h2>Mevcut krediler</h2></div>${loans.map(l=>`<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(l.krediTuru)}</b><span class="tag ${l.aktif?'warn':'good'}">${l.aktif?'AKTİF':'KAPANDI'}</span></div><p>Kalan ${money(l.kalanBorc)} · Taksit ${money(l.taksitTutari)} · Gecikme ${int(l.gecikmeSayisi)}</p></div>`).join('')||'<div class="notice">Kredi yok.</div>'}</div></div>`}
function renderProtocols(d){const declared=d.kodTabanliYayinlar?.protokoller||[],market=d.protokoller||[];$('#protocols').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Kodlanan protokoller</h2></div>${declared.map(x=>{const p=x.protokol||{},id=`${p.protokolKimligi}@${p.surum}`;return `<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</span></div><p>${esc(p.aciklama)}</p>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Lisans${selectField(`proto:${id}:model`,'acik',[['acik','Açık'],['tek-seferlik','Tek seferlik'],['abonelik','Abonelik'],['karma','Karma']])}</label><label>Benimseme${field(`proto:${id}:adopt`,0,'number','min="0"')}</label><label>Tick lisansı${field(`proto:${id}:tick`,0,'number','min="0"')}</label><button type="button" data-action="protocol-publish" data-id="${esc(id)}" ${!x.gecerli?'disabled':''}>Yayınla</button></div>`}</div>`}).join('')||'<div class="notice">Protokol manifesti yok.</div>'}</div><div class="card"><div class="title"><h2>Protokol piyasası</h2></div>${market.map(p=>`<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><button type="button" class="small" data-action="protocol-adopt" data-id="${esc(p.protokolKimligi)}">Benimse</button></div><p>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</p></div>`).join('')||'<div class="notice">Piyasada protokol yok.</div>'}</div></div>`}
function renderContracts(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[];$('#contracts').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Açık SLA teklifleri</h2></div>${offers.map(o=>`<div class="item" style="margin-bottom:8px"><div class="row"><div><b>${esc(o.baslik)}</b><p>${esc(o.kategori)} · ${int(o.sureTick)} tick · Kapasite ${int(o.gerekliKapasite)}</p></div><button type="button" class="small" data-action="contract" data-id="${esc(o.teklifKimligi)}">Kabul et</button></div><div class="tags"><span class="tag good">${money(o.tickOdemesi)}/tick</span><span class="tag bad">${money(o.ihlalCezasi)} ceza</span></div></div>`).join('')||'<div class="notice">Açık teklif yok.</div>'}</div><div class="card"><div class="title"><h2>Sözleşmeler</h2></div>${active.map(s=>`<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(s.baslik)}</b><span class="tag ${s.aktif?'good':'bad'}">${s.aktif?'AKTİF':'BİTTİ'}</span></div><p>Başarı ${int(s.basariliTickSayisi)} · İhlal ${int(s.ihlalSayisi)} · Kapasite şartı ${int(s.gerekliKapasite)}</p></div>`).join('')||'<div class="notice">Sözleşme yok.</div>'}</div></div>`}
function renderAccount(d){const i=d.isletim||{};$('#account').innerHTML=`<div class="grid"><div class="card"><h2>Parola değiştir</h2><label>Mevcut parola${field('account:old','', 'password','autocomplete="current-password"')}</label><label>Yeni parola${field('account:new','', 'password','autocomplete="new-password"')}</label><button type="button" class="full" data-action="password">Parolayı değiştir</button></div><div class="card"><h2>Risk ve sürdürülebilirlik</h2><div class="grid4">${[['Operasyon riski',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ödenemeyen gider',money(i.odenemeyenGider)],['Temerrüt',int(i.temerrutSayisi)],['Kredi notu',int(i.krediNotu)],['İşletme gideri',money(i.toplamIsletmeGideri)],['Yatırım harcaması',money(i.toplamYatirimHarcamasi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function getValue(key){const e=document.querySelector(`[data-key="${CSS.escape(key)}"]`);return e?e.value:(S.drafts.get(key)??'')}
function numberValue(key){const x=Number(getValue(key));if(!Number.isFinite(x))throw new Error('Sayısal değer geçersiz.');return x}
function findService(id){const h=serviceList().find(x=>`${x.hizmetKimligi}@${x.hizmetSurumu}`===id);if(!h)throw new Error('Hizmet bulunamadı.');return h}
function findProduct(id){const p=(S.data?.isletim?.urunler||[]).find(x=>x.urunKimligi===id);if(!p)throw new Error('Ürün bulunamadı.');return p}
async function run(button,job){if(S.busy)return;S.busy=true;$('#busy').classList.add('on');const old=button.textContent;button.disabled=true;button.textContent='İşleniyor…';try{const r=await job();toast(r.aciklama||'İşlem tamamlandı.');await refresh(true)}catch(e){toast(e.message,false)}finally{S.busy=false;button.disabled=false;button.textContent=old;$('#busy').classList.remove('on')}}
async function action(button){const a=button.dataset.action,id=button.dataset.id||'';await run(button,async()=>{if(a==='service-price'){const h=findService(id);return request('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:numberValue(`svc:${id}:price`)})}if(a==='service-toggle'){const h=findService(id);return request('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif})}if(a==='service-cap'){const h=findService(id);return request('/api/hizmet/kapasite',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,eklenecekKapasite:numberValue(`svc:${id}:cap`)})}if(a==='app-publish')return request('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:getValue(`app:${id}:model`),abonelikUcreti:numberValue(`app:${id}:sub`),kullanimBasinaUcret:numberValue(`app:${id}:use`)});if(a==='product-save'||a==='product-toggle'){const p=findProduct(id);return request('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:numberValue(`prd:${id}:sub`),kullanimBasinaUcret:numberValue(`prd:${id}:use`),aktif:a==='product-toggle'?!p.aktif:p.aktif})}if(a==='product-cap')return request('/api/uygulama/kapasite',{urunKimligi:id,eklenecekKapasite:numberValue(`prd:${id}:cap`)});if(a==='investment')return request('/api/yatirim',{yatirimTuru:id});if(a==='loan')return request('/api/kredi',{krediTuru:id,tutar:numberValue(`loan:${id}`)});if(a==='protocol-publish'){const at=id.lastIndexOf('@'),kimlik=id.slice(0,at),surum=id.slice(at+1);return request('/api/protokol/yayinla',{protokolKimligi:kimlik,surum,lisansModeli:getValue(`proto:${id}:model`),benimsemeBedeli:numberValue(`proto:${id}:adopt`),tickLisansBedeli:numberValue(`proto:${id}:tick`)})}if(a==='protocol-adopt')return request('/api/protokol/benimse',{protokolKimligi:id});if(a==='contract')return request('/api/sozlesme/kabul',{teklifKimligi:id});if(a==='password')return request('/api/parola',{eskiParola:getValue('account:old'),yeniParola:getValue('account:new')});throw new Error('Bilinmeyen işlem.')})}
document.addEventListener('input',e=>{if(e.target?.dataset?.key)S.drafts.set(e.target.dataset.key,e.target.value)});document.addEventListener('change',e=>{if(e.target?.dataset?.key)S.drafts.set(e.target.dataset.key,e.target.value)});document.addEventListener('focusout',()=>setTimeout(()=>{if(S.pending&&!editing()){const d=S.pending;S.pending=null;renderAll(d)}},150));document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b){e.preventDefault();action(b)}});$('#login').addEventListener('click',login);$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').addEventListener('click',logout);
request('/api/durum').then(()=>{showApp();refresh(true);startPolling()}).catch(()=>{});switchPanel(location.hash.slice(1)||'overview');
</script>
</body>
</html>
""";
}
